// Pteronautics Loom's service worker: makes the app work offline and installable.
// Generated by tools/precache.py from tools/sw.template.js. Do not edit sw.js by hand.
//
// Every app file is cached when the worker installs. While online, files still come from the
// network first (so a new version shows up on the next load) and the cache is refreshed;
// offline, or when the network is slow to answer, the cached copy is used.
const CACHE = '__CACHE__';
const FILES = __FILES__;
const WAIT = 4000;
const LISTED = new Set(FILES);

self.addEventListener('install', (ev) => {
  ev.waitUntil(caches.open(CACHE).then((c) => c.addAll(FILES.map((f) => new Request(f, { cache: 'reload' })))).then(() => self.skipWaiting()));
});

self.addEventListener('activate', (ev) => {
  ev.waitUntil(caches.keys().then((keys) => Promise.all(keys.filter((k) => k.startsWith('loom-') && k !== CACHE).map((k) => caches.delete(k)))).then(() => self.clients.claim()));
});

/** The app file a request is for, relative to the app's folder, or null. @param {Request} req */
function appFile(req) {
  const url = new URL(req.url);
  const base = new URL(self.registration.scope);
  if (url.origin !== base.origin || !url.pathname.startsWith(base.pathname)) return null;
  if (req.mode === 'navigate') return 'index.html';
  const rel = decodeURIComponent(url.pathname.slice(base.pathname.length));
  return LISTED.has(rel) ? rel : null;
}

self.addEventListener('fetch', (ev) => {
  const req = ev.request;
  if (req.method !== 'GET') return;
  const file = appFile(req);
  if (!file) return;
  ev.respondWith((async () => {
    const cache = await caches.open(CACHE);
    const fromNet = fetch(req).then((res) => {
      if (res.ok && res.type === 'basic' && req.mode !== 'navigate') cache.put(file, res.clone());
      else if (res.ok && req.mode === 'navigate' && new URL(req.url).pathname.endsWith('/')) cache.put('index.html', res.clone());
      return res;
    });
    fromNet.catch(() => null); // answered from the cache instead; nothing to report
    const late = new Promise((resolve) => setTimeout(resolve, WAIT, null));
    try {
      const res = await Promise.race([fromNet, late]);
      if (res) return res;
    } catch { /* offline: use the cache */ }
    const cached = await cache.match(file);
    return cached || fromNet;
  })());
});
